/**  Request payload for `sessions.media.scrub`. */
export type SessionMediaScrubRequest = {
	/**  Write a pre-scrub vault archive before rewriting messages. */
	createBackup: boolean,
};

/**
 *  Payload of a `settings.changed` event: the section whose blob changed.
 *
 *  Carries no values — a client must re-read the section through
 *  `settings.get` so it cannot cache a stale snapshot from the event.
 */
export type SettingsChangedData = {
	/**  Settings section name accepted by `settings.get`/`settings.set`. */
	section: string,
	/**  Monotonic publication sequence (stamped by the bus). */
	seq: number,
	/**  Producer timestamp, unix epoch milliseconds (stamped by the bus). */
	ts_ms: number,
};

/**  `data` payload of a `settings.get` reply. */
export type SettingsGetReply = {
	/**  Settings section name. */
	section: string,
	/**  Settings data as JSON string. */
	settings: string,
};

/**  `data` payload of a `settings.set` reply. */
export type SettingsSetReply = {
	/**  Whether the save succeeded. */
	ok: boolean,
};

/**
 *  Payload of a `status.changed` event: coarse, secret-free core health.
 *
 *  Mirrors the [`CoreStatusReply`] discipline: it MUST NOT carry auth tokens,
 *  D-Bus tokens, provider configs, API keys, prompts, secret-revealing paths or
 *  raw memory.
 */
export type StatusChangedData = {
	/**  Whether the core service is available. */
	core_available: boolean,
	/**  Whether the underlying store is available. */
	store_available: boolean,
	/**  Coarse store health (`"ok"` or `"unavailable"`). */
	store_health: string,
	/**  Monotonic publication sequence (stamped by the bus). */
	seq: number,
	/**  Producer timestamp, unix epoch milliseconds (stamped by the bus). */
	ts_ms: number,
};

/**  A short-term-memory daily summary surfaced to thin clients. */
export type StmmSummary = {
	/**  Summary id. */
	id: string,
	/**  Day key. */
	day: string,
	/**  Body. */
	content: string,
	/**  Source session ids. */
	source_session_ids: string[],
	/**  Token estimate. */
	token_estimate: number,
	/**  Created timestamp. */
	created_at: number,
};

/**  Payload of a `token.delta` event: one streamed LLM token. */
export type TokenDeltaData = {
	/**  Chat session id the turn belongs to. */
	session_id: string,
	/**  Message id the token stream belongs to. */
	message_id: string,
	/**  Raw token text (may be empty only on the terminal event). */
	delta: string,
	/**  Zero-based token index within the turn. */
	index: number,
	/**
	 *  `true` on the final token of the turn. Wire name is `final`; Rust
	 *  cannot use the reserved keyword as a field name.
	 */
	final: boolean,
	/**  Monotonic publication sequence (stamped by the bus). */
	seq: number,
	/**  Producer timestamp, unix epoch milliseconds (stamped by the bus). */
	ts_ms: number,
	/**
	 *  Terminal reason of the turn: `complete`, `cancelled` or `error`.
	 *  Absent on non-final deltas; absent on a final frame from an old daemon
	 *  means `complete`. Clients must not speak `cancelled`/`error` turns.
	 */
	reason?: string | null,
};

/**  Reply payload for `vault.archive.apply`. */
export type VaultArchiveApplyReply = {
	/**  Sessions inserted. */
	sessionsInserted: number,
	/**  Sessions skipped because the id already exists. */
	sessionsSkipped: number,
	/**  Messages inserted. */
	messagesInserted: number,
	/**  Messages skipped because the id already exists. */
	messagesSkipped: number,
	/**  Summaries inserted. */
	summariesInserted: number,
	/**  Journal entries inserted. */
	journalEntriesInserted: number,
	/**  Domains applied (`chats`, `memory`). */
	applied: string[],
	/**  Domains present but intentionally not applied. */
	notApplied: string[],
};

/**
 *  Request payload for `vault.archive.collect`.
 *
 *  `domains` accepts `characters`, `chats`, `memory` and `backgrounds`.
 *  `providers` is rejected: provider configuration contains API credentials
 *  and must never cross the gateway wire.
 */
export type VaultArchiveCollectRequest = {
	/**  Data domains to include in the archive. */
	domains: string[],
};

/**  Reply payload for `vault.archive.inspect` (metadata only, never contents). */
export type VaultArchiveInspectReply = {
	/**  Format marker (`airi-vault`). */
	format: string,
	/**  Format version. */
	version: number,
	/**  Archive creation time in epoch milliseconds, when present. */
	createdAt?: number,
	/**
	 *  Whether the archive advertises provider credentials.
	 *
	 *  Such archives are rejected by `vault.archive.apply`; the flag exists so
	 *  callers can explain the rejection without receiving the credentials.
	 */
	includesSecrets: boolean,
	/**  Per-domain counts and byte sizes (no payload bytes). */
	domains: unknown[],
	/**  Session count inside the archive. */
	sessionCount: number,
	/**  Message count inside the archive. */
	messageCount: number,
	/**  Companion names found in the archive. */
	companionNames: string[],
};

/**
 *  Reply payload for `vault.archive.collect`.
 *
 *  The archive is a base64-encoded ZIP. The daemon refuses to include the
 *  providers domain, so no credentials are present in `archive`.
 */
export type VaultArchiveReply = {
	/**  Base64-encoded stored ZIP archive. */
	archive: string,
	/**  Decoded archive byte size. */
	bytes: number,
	/**  Data domains actually included (`characters|chats|memory|backgrounds`). */
	domains: string[],
};

/**
 *  Request payload for `vault.archive.inspect` and `vault.archive.apply`.
 *
 *  The archive is a base64-encoded ZIP previously returned by
 *  `vault.archive.collect`.
 */
export type VaultArchiveRequest = {
	/**  Base64-encoded vault archive. */
	archive: string,
};

/**  Vault statistics data. */
export type VaultStatsData = {
	/**  Chat domain statistics. */
	chats: DomainStatsData,
	/**  Memory domain statistics. */
	memory: MemoryStatsData,
	/**  Provider domain statistics. */
	providers: ProviderStatsData,
	/**  Character domain statistics. */
	characters: CharacterStatsData,
};

/**
 *  `data` payload of a `vault.status` reply.
 *
 *  Vault statistics (counts and byte sizes only, no secret material).
 */
export type VaultStatusReply = {
	/**  Whether the vault is available. */
	available: boolean,
	/**  Vault statistics. */
	stats: VaultStatsData | null,
};
